<?php
declare(strict_types=1);
require dirname(__DIR__) . '/vendor/autoload.php';
use App\Domain\{Rules, Problem, CustomerService, SettingsService, InvoiceService, QrService};
use App\Infrastructure\Database;
use App\Pdf\PdfService;
$root = dirname(__DIR__);
$testDir = $root . '/temp/verification';
if (!is_dir($testDir)) mkdir($testDir, 0700, true);
$path = $testDir . '/domain-' . bin2hex(random_bytes(5)) . '.sqlite';
$db = new Database($path); $db->migrate();
$customers = new CustomerService($db); $settings = new SettingsService($db); $qr = new QrService; $pdf = new PdfService($qr, $root . '/temp'); $invoices = new InvoiceService($db,$customers,$settings,$pdf);
$checks=0;
function check(bool $condition, string $label): void {global $checks; if(!$condition) throw new RuntimeException('FAIL: '.$label); $checks++; echo "PASS $label\n";}
function rejected(callable $action, int $status, string $label): void {try {$action();} catch(Problem $e) {check($e->status===$status,$label);return;} throw new RuntimeException('Expected rejection: '.$label);}
$party=['name'=>'Test dodávateľ s. r. o.', 'street'=>'Testovacia 1', 'zip'=>'010 01', 'city'=>'Žilina', 'country'=>'Slovensko', 'ico'=>'12345678', 'dic'=>'1234567890', 'vatId'=>'SK1234567890', 'iban'=>'SK5000000000000000000001','bic'=>'TESTSK00'];
$supplier=Rules::party($party,true);
$db->query('INSERT INTO settings(id,data) VALUES(1,?)',[Database::json($supplier)]);
$db->query('INSERT INTO sequences(year,last_number) VALUES(2026,13)');
$customer=$customers->save($party+['email'=>'test@example.test']);
check(Rules::validIban($supplier['iban']) && !Rules::validIban('SK5000000000000000000002'),'IBAN checksum');
rejected(fn()=>Rules::party(array_replace($party,['name'=>"Injected\tIBAN"])),422,'Control character injection rejected');
rejected(fn()=>Rules::date('2026-02-30','Test',true),422,'Impossible calendar date rejected');
$calc=Rules::totals([['quantity'=>'1.000','unitPrice'=>'2880.00','vatRate'=>23]]);
check($calc['net']===288000 && $calc['vat']===66240 && $calc['gross']===354240,'Reference invoice exact 3542.40 EUR');
$calc=Rules::totals([['quantity'=>'0.125','unitPrice'=>'0.04','vatRate'=>23],['quantity'=>'3.000','unitPrice'=>'0.10','vatRate'=>19]]);
check($calc['net']===31 && $calc['vat']===6 && $calc['gross']===37,'Half-cent rounding and mixed VAT');
$draft=$invoices->blank(); $draft['customerId']=$customer['id']; $draft['issueDate']='2026-10-15'; $draft['deliveryDate']='2026-10-15'; $draft['dueDate']='2026-10-29'; $draft['items']=[['description'=>'Vývoj & test <script>alert(1)</script> „Žilina“','quantity'=>'1','unit'=>'JV','unitPrice'=>'2880.00','vatRate'=>23]];
$draft['qrProfiles']=['sk','epc'];
$saved=$invoices->save($draft);
check($saved['number']===null && $saved['version']===1,'Draft has no invoice number');
rejected(fn()=>$invoices->save($draft),409,'Duplicate create safely reconciles by client key');
$revised=$invoices->save($saved);
rejected(fn()=>$invoices->save($saved),409,'Stale draft cannot overwrite');
$changedCustomer=$customers->save(array_replace($customer,['name'=>'Changed customer']));
check($invoices->get($revised['id'])['customer']['name']===$customer['name'],'Customer details are frozen on saved invoice');
rejected(fn()=>$customers->save($customer),409,'Customer stale edit cannot overwrite');
rejected(fn()=>$invoices->issue($revised['id'],1),409,'Stale issue rejected');
$issued=$invoices->issue($revised['id'],$revised['version']);
check($issued['number']==='20260014' && $issued['totals']['gross']===354240,'First issued number after 13 is 14');
$binary=$invoices->pdf($issued['id']); file_put_contents($testDir.'/invoice-sk-epc.pdf',$binary);
check(str_starts_with($binary,'%PDF') && strlen($binary)>15000,'Real PDF generated and stored');
check($invoices->issue($issued['id'],1)['number']==='20260014','Retry issuing returns same invoice');
$originalIssued=$issued;
$sequenceBeforeEdit=$db->query('SELECT * FROM sequences ORDER BY year')->fetchAll();
$change=$issued; $change['items'][0]['unitPrice']='3000.00'; $change['note']='Opravená vystavená faktúra';
$change['issueDate']='2027-01-01'; $change['deliveryDate']='2027-01-01'; $change['dueDate']='2027-01-15';
$change['number']='20279999'; $change['status']='draft'; $change['qrProfiles']=['cz','epc'];
$edited=$invoices->save($change);
check($edited['number']==='20260014' && $edited['status']==='issued' && $edited['totals']['gross']===369000,'Issued edit preserves stored number/status and updates totals');
check($db->query('SELECT * FROM sequences ORDER BY year')->fetchAll()===$sequenceBeforeEdit,'Editing issue year never consumes or changes a number');
$editedPdf=$invoices->pdf($edited['id']); file_put_contents($testDir.'/invoice-edited.pdf',$editedPdf);
check(hash('sha256',$editedPdf)!==hash('sha256',$binary) && str_contains($qr->payload($edited,'cz'),'AM:3690.00') && explode("\n",$qr->payload($edited,'epc'))[7]==='EUR3690.00','Issued edit replaces PDF and QR with corrected amount');
rejected(fn()=>$invoices->save($originalIssued),409,'Stale issued edit cannot overwrite');
rejected(fn()=>$invoices->delete($edited['id'],$originalIssued['version']),409,'Stale issued deletion cannot remove a newer version');
$invalidEdit=$edited; $invalidEdit['items'][0]['description']='';
rejected(fn()=>$invoices->save($invalidEdit),422,'Issued edit still requires complete invoice data');
$invalidQr=$edited; $invalidQr['items'][0]['unitPrice']='10000000.00'; $invalidQr['qrProfiles']=['cz'];
rejected(fn()=>$invoices->save($invalidQr),422,'PDF/QR generation failure rejects issued edit');
check($invoices->get($edited['id'])['version']===$edited['version'] && $invoices->pdf($edited['id'])===$editedPdf,'Failed edit leaves data, version and PDF unchanged');
$issued=$invoices->save(array_replace($originalIssued,['version'=>$edited['version']]));
$binary=$invoices->pdf($issued['id']);
$settings->save(array_replace($settings->get(),['name'=>'Updated supplier']));
check(hash('sha256',$binary)===hash('sha256',$invoices->pdf($issued['id'])),'Stored PDF unchanged after supplier edit');
$copy=$invoices->copy($issued['id']);
check($copy['number']===null && $copy['supplier']['name']==='Updated supplier' && $copy['customer']['name']==='Changed customer','Copy uses fresh supplier and customer without consuming number');
$before=$db->query('SELECT last_number FROM sequences WHERE year=2026')->fetchColumn();
$invalid=$copy; $invalid['items'][0]['description']=''; $invalid=$invoices->save($invalid);
rejected(fn()=>$invoices->issue($invalid['id'],$invalid['version']),422,'Incomplete draft cannot be issued');
check($db->query('SELECT last_number FROM sequences WHERE year=2026')->fetchColumn()===$before,'Failed issue does not consume number');
$copy=$invoices->get($copy['id']); $copy['items']=$issued['items']; $copy['qrProfiles']=['cz']; $copy=$invoices->save($copy); $cz=$invoices->issue($copy['id'],$copy['version']);
file_put_contents($testDir.'/invoice-cz.pdf',$invoices->pdf($cz['id']));
$payloads=[];
foreach(['sk','cz','epc'] as $profile) {$payloads[$profile]=$qr->payload($issued,$profile); $qrInvoice=$issued; $qrInvoice['qrProfiles']=[$profile]; $image=$qr->images($qrInvoice)[0]; file_put_contents($testDir.'/qr-'.$profile.'.png',base64_decode(explode(',',$image['dataUri'],2)[1]));}
file_put_contents($testDir.'/qr-payloads.json',Database::json($payloads));
check(str_contains($payloads['cz'],'AM:3542.40*CC:EUR') && str_contains($payloads['cz'],'X-VS:20260014'),'SPAYD amount currency reference');
check(explode("\n",$payloads['epc'])[7]==='EUR3542.40' && strlen($payloads['epc'])<=331,'EPC amount and byte limit');
$long=$invoices->copy($issued['id']); $long['qrProfiles']=['sk','cz']; $long['note']=str_repeat('Dlhšia poznámka s diakritikou. ',20); $long['items']=[];
for($i=1;$i<=60;$i++) $long['items'][]=['description'=>"Položka $i — Vývoj a testovanie slovenských znakov čšťžýáíé. ".str_repeat('Podrobný opis prác a výsledkov. ',5),'quantity'=>'2.125','unit'=>'hod','unitPrice'=>'15.50','vatRate'=> $i%2 ? 23 : 19];
$long=$invoices->save($long); $long=$invoices->issue($long['id'],$long['version']); file_put_contents($testDir.'/invoice-multipage.pdf',$invoices->pdf($long['id']));
check(strlen($invoices->pdf($long['id']))>20000,'Long invoice generated');
$draftCopy=$invoices->copy($issued['id']); $invoices->delete($draftCopy['id'],$draftCopy['version']); rejected(fn()=>$invoices->get($draftCopy['id']),404,'Draft deletion works');
$customers->archive($changedCustomer['id'],$changedCustomer['version'],true); check(count($customers->all())===0 && count($customers->all(true))===1,'Customer archive preserves historical invoices');
check($invoices->get($issued['id'])['customer']['name']===$customer['name'],'Archive leaves issued customer snapshot unchanged');
// A fresh year has an independent sequence.
$new=$invoices->blank(); $new['customerId']=$customer['id']; $new['issueDate']='2027-01-01'; $new['deliveryDate']='2027-01-01'; $new['dueDate']='2027-01-15'; $new['items']=$issued['items'];
$archived=$customers->get($customer['id']); $customers->archive($archived['id'],$archived['version'],false);
$new=$invoices->save($new); $new=$invoices->issue($new['id'],$new['version']); check($new['number']==='20270001','Year rollover starts at 0001');
echo "\n$checks checks passed. Artefacts: $testDir\n";
$race1=$invoices->copy($issued['id']); $race2=$invoices->copy($issued['id']);
$processes=[];
foreach([$race1,$race2,$race1] as $race) {
    $process=proc_open([PHP_BINARY,__DIR__.'/issue_worker.php',$path,(string)$race['id'],(string)$race['version']],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);
    if(!is_resource($process)) throw new RuntimeException('Cannot start race worker');
    fclose($pipes[0]); $processes[]=[$process,$pipes];
}
$numbers=[];
foreach($processes as [$process,$pipes]) {$output=stream_get_contents($pipes[1]);$error=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);check(proc_close($process)===0,'Concurrent issue worker succeeds: '.$error);$numbers[]=$output;}
check($numbers[0]===$numbers[2] && $numbers[0]!==$numbers[1],'Concurrent issue retry cannot duplicate or consume extra number');
// Delete both states, retain the high-water mark, and never recreate a deleted record through save.
$deleteTarget=$invoices->get($race2['id']);
$beforeDelete=$db->query('SELECT last_number FROM sequences WHERE year=2026')->fetchColumn();
$invoices->delete($deleteTarget['id'],$deleteTarget['version']);
rejected(fn()=>$invoices->get($deleteTarget['id']),404,'Issued invoice can be deleted');
rejected(fn()=>$invoices->pdf($deleteTarget['id']),404,'Deleted issued PDF is no longer downloadable');
rejected(fn()=>$invoices->save($deleteTarget),404,'Stale save cannot recreate a deleted invoice');
check($db->query('SELECT last_number FROM sequences WHERE year=2026')->fetchColumn()===$beforeDelete,'Deleting issued invoice does not rewind sequence');
$afterDelete=$invoices->copy($issued['id']); $afterDelete=$invoices->issue($afterDelete['id'],$afterDelete['version']);
check((int)substr($afterDelete['number'],4)===(int)$beforeDelete+1,'Next invoice never reuses a deleted number');
$invoices->delete($afterDelete['id'],$afterDelete['version']);
echo "$checks total checks passed including concurrent issue and edit/delete.\n";
